parameters.jsCode:
const pairs = $input.all().map(item => item.json);
const batchId = $('Webhook Trigger (loan-match)').first().json.body.batch_id;
const totalSqlPairs = pairs.length;

// Group by user_id
const byUser = {};
for (const p of pairs) {
  if (!byUser[p.user_id]) byUser[p.user_id] = [];
  byUser[p.user_id].push(p);
}

const topKPairs = [];
const clearMatches = [];
const ambiguousPairs = [];

for (const userId in byUser) {
  const userProducts = byUser[userId];
  // Sort by lowest interest rate
  userProducts.sort((a, b) => {
    const ra = a.interest_rate_min !== null ? Number(a.interest_rate_min) : 999;
    const rb = b.interest_rate_min !== null ? Number(b.interest_rate_min) : 999;
    return ra - rb;
  });

  // Top K (5)
  const top5 = userProducts.slice(0, 5);
  for (const pair of top5) {
    topKPairs.push(pair);
    // Margin evaluation
    const marginScore = Number(pair.score_margin) || 0;
    const incMargin = Number(pair.income_margin_pct) || 0;
    const hasQual = Boolean(pair.has_qualitative_rules);
    const hasIncomeRule = pair.min_monthly_income !== null;

    if (incMargin >= 20 && marginScore >= 30 && !hasQual && hasIncomeRule) {
      clearMatches.push({
        ...pair,
        stage: 'rules',
        score: marginScore,
        reason: `Clear match: rate ${pair.interest_rate_min}%, +${incMargin}% income margin`
      });
    } else {
      ambiguousPairs.push({
        ...pair,
        profile_key: `${Math.floor(Number(pair.monthly_income)/10000)*10}k_${Math.floor(Number(pair.credit_score)/50)*50}_${Math.floor(Number(pair.age)/5)*5}_${pair.employment_status}`
      });
    }
  }
}

const rawMatches = JSON.stringify(clearMatches);
const sqlEscapedClearMatches = rawMatches.replace(/'/g, "''");

return [{
  json: {
    batch_id: batchId,
    pairs_after_sql: totalSqlPairs,
    pairs_after_rules: topKPairs.length,
    clearMatches,
    clearCount: clearMatches.length,
    ambiguousPairs,
    ambiguousCount: ambiguousPairs.length,
    clearMatchesJson: rawMatches,
    sqlEscapedClearMatches: sqlEscapedClearMatches
  }
}];
